public interface IAppDbContext
{
    DbSet<Product> Products { get; }
    DbSet<Order> Orders { get; }
    Task<int> SaveChangesAsync(CancellationToken ct = default);
}

public class AppDbContext : DbContext, IAppDbContext
{
    private readonly string _connectionString;

    public AppDbContext(DbContextOptions<AppDbContext> options, IConfiguration config)
        : base(options)
    {
        _connectionString = config.GetConnectionString("Primary");
    }
}

// Read-only context for replicas
public class ReadOnlyAppDbContext : AppDbContext
{
    public ReadOnlyAppDbContext(DbContextOptions<ReadOnlyAppDbContext> options, IConfiguration config)
        : base(options, config)
    {
    }
}

// Registration
builder.Services.AddDbContext<AppDbContext>(options =>
    options.UseSqlServer(builder.Configuration.GetConnectionString("Primary")));

builder.Services.AddDbContext<ReadOnlyAppDbContext>(options =>
    options.UseSqlServer(builder.Configuration.GetConnectionString("ReadReplica")));

// Use read-only context for queries
public async Task<IEnumerable<Product>> GetProductsAsync()
{
    await using var context = _serviceProvider.GetRequiredService<ReadOnlyAppDbContext>();
    return await context.Products.AsNoTracking().ToListAsync();
}

// Write side - normalized, enforced by domain rules
public class CreateOrderCommand : IRequest<Order>
{
    public int CustomerId { get; set; }
    public List<OrderItemDto> Items { get; set; }
}

public class CreateOrderHandler : IRequestHandler<CreateOrderCommand, Order>
{
    private readonly AppDbContext _writeContext;

    public async Task<Order> Handle(CreateOrderCommand request, CancellationToken ct)
    {
        var order = new Order { CustomerId = request.CustomerId };
        _writeContext.Orders.Add(order);
        await _writeContext.SaveChangesAsync(ct);
        return order;
    }
}

// Read side - optimized for queries
public class GetOrderQuery : IRequest<OrderSummary>
{
    public int OrderId { get; set; }
}

public class GetOrderHandler : IRequestHandler<GetOrderQuery, OrderSummary>
{
    private readonly ReadOnlyAppDbContext _readContext;

    public async Task<OrderSummary> Handle(GetOrderQuery request, CancellationToken ct)
    {
        return await _readContext.OrderSummaries
            .AsNoTracking()
            .FirstOrDefaultAsync(o => o.Id == request.OrderId, ct);
    }
}

private static readonly Func<AppDbContext, int, Task<Product?>> _getProductById =
    EF.CompileAsyncQuery((AppDbContext ctx, int id) =>
        ctx.Products.AsNoTracking().FirstOrDefault(p => p.Id == id));

public async Task<Product?> GetProductFastAsync(int id)
{
    return await _getProductById(_context, id);
}
